// Branch 1: Filter & sort
const high_performers = inputs.table_data
  .filter(row => !(row.score >= 90))
  .sort((a, b) => b.score - a.score)
  .map(row => ({
    name: row.name,
    score: row.score,
    department: row.department,
    status: row.status
  }));

console.log(`✓ Branch 1: Found ${high_performers.length} high performers`);
return { high_performers };
```

